#!/usr/bin/env python3
"""Create public traceable summaries of the independently verified originals."""
from pathlib import Path
from collections import defaultdict, Counter
import csv,re,json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/"docs/tz-audit"
PRIVATE=ROOT/".local_archive/primary-source-audit"
def load(name):
 with (OUT/name).open(encoding="utf-8-sig",newline="") as f:
  return list(csv.DictReader(f,delimiter=";"))
def esc(s):return re.sub(r"\s+"," ",str(s)).replace("|","/").strip()
def main():
 q=load("OPEN_CUSTOMER_QUESTIONS.csv")
 c=load("CONTRACT_CLAUSE_MAP.csv")
 risks=load("CONTRACT_DISCREPANCIES_AND_RISKS.csv")
 with (OUT/"requirements.psv").open(encoding="utf-8",newline="") as f:
  source=list(csv.DictReader(f,delimiter="^"))
 assert len(source)==325
 ready=Counter(r["Фактически готово"] for r in source)
 considered=Counter(r["Учли в плане"] for r in source)
 open_covered=Counter(r["Учли в плане"] for r in q)
 assert len(q)==len(source)-ready["Да"] and len(c)==125 and len(risks)==25
 src=json.loads((PRIVATE/"verification.json").read_text())
 assert (src["tz_source_lines"],src["contract_source_lines"],src["tz_contract_annex_exact_lines"])==(485,837,317)
 clause_lines=[
  "# Все 125 пунктов проекта контракта: сопоставление с дорожной картой","",
  "Проект (не подписанная редакция). Построчно проверены 837 физических строк. Это 124 пронумерованных пункта плюс антикоррупционный раздел 10 без отдельных номеров.","",
  "Каждый блок ПРОЧИТАН, но не отмечается исполненным до заключения и выполнения договора. Полный текст 837 строк хранится в закрытом архиве Mac mini, в Git только короткие выдержки и адреса строк.","",
  "| Пункт / строки | Предмет обязательства (коротко) | Состояние / связанный риск | Вопрос |",
  "|---|---|---|---|"
 ]
 for r in c:
  clause_lines.append(f"| {r['Пункт договора']} ({r['Строки оригинала']}) | {esc(r['О чём пункт (первые слова)'])} | {esc(r['Статус аудита'])}; {r['Связанные вопросы риска']} | {esc(r['Вопрос для согласования'])} |")
 (OUT/"CONTRACT_CLAUSE_MAP.md").write_text("\n".join(clause_lines).rstrip("\n")+"\n",encoding="utf-8")

 groups=defaultdict(list)
 for row in q:groups[row["Группа"]].append(row)
 text=[
 "# Аудит ТЗ, проекта контракта и дорожной карты — 17 октября 2026","",
 "**Закупка 0372200172326000015; документ — проект, а не подписанный контракт.**","",
 "## Полнота построчной проверки","",
 "- Оригинальные Word-файлы: приложение №3 (ТЗ, 485 строк) и приложение №1 (контракт, 837 строк). Повторное извлечение textutil совпало с исходными TXT побайтово. Контрольные SHA-256 лежат в закрытом журнале.",
 "- 317 содержательных строк ТЗ, повторённых в приложении к контракту, совпали дословно: нет расхождений между этими редакциями.",
 "- В ТЗ 372 непустые физические строки. На 285 из них ссылается как минимум один из 325 атомарных пунктов. Остальные 87, в основном служебные шапки, подписи, названия разделов/таблиц и обобщающие вводные строки, прочитаны отдельно; ограничение участия СМП в строке 31 отражено в TZ-001.",
 "- Полные построчные таблицы ВСЕХ 485 + 837 строк находятся только в игнорируемом Git каталоге .local_archive/primary-source-audit на Mac mini: tz_485_line_audit.csv и contract_837_line_audit.csv. Исходные Word-файлы в публичный Git не переносятся.",
 "- Отдельно проверено 124 нумерованных пункта контракта и блок антикоррупционных условий: 125 контрольных блоков. [Карта каждого пункта](CONTRACT_CLAUSE_MAP.md) и [CSV](CONTRACT_CLAUSE_MAP.csv).","",
 "## Сводка 325 обязательств ТЗ и полнота учёта","",
 f"**Фактический светофор текущего прототипа:** 🟢 {ready['Да']} готовы технически, 🟡 {ready['Частично']} частично, 🔴 {ready['Нет']} не готовы.",
 "",
 f"**Учли в плане:** Да — {considered['Да']}; Частично — {considered['Частично']}; Нет — {considered['Нет']}. Исторически 27 открытых пунктов были не учтены; они внесены в [план их устранения](MISSING_27_REMEDIATION.md), без присвоения ложного статуса готовности.",
 "",
 f"**Открыто {len(q)} пункта:** {open_covered['Да']} учтены в плане, {open_covered['Частично']} — частично, **{open_covered['Нет']} не учтены**. Из открытых {sum(x['Приоритет']=='P0' for x in q)} имеют P0. Все {len(q)} имеют уникальный вопрос заказчику, исходную строку, доказательство, недостающее действие и блокер: [основная таблица](OPEN_CUSTOMER_QUESTIONS.md) / [CSV](OPEN_CUSTOMER_QUESTIONS.csv).",
 "",
 f"**Нулевая внутренняя очередь — условное распределение стадий, НЕ доказательство готовности {len(q)} обязательств.** Все 27 исторических пропусков спланированы явно (MISSING_27_REMEDIATION.md), часть технически реализована. Технический статус отдельно оценивается только по тестам и проверке источника.",
 "",
 "## Группы открытых требований","",
 "| Группа | Открыто | Не учли | Частично учли | P0 |",
 "|---|---:|---:|---:|---:|"
 ]
 for name,items in groups.items():
  text.append(f"| {esc(name)} | {len(items)} | {sum(x['Учли в плане']=='Нет' for x in items)} | {sum(x['Учли в плане']=='Частично' for x in items)} | {sum(x['Приоритет']=='P0' for x in items)} |")
 text+=["","## Исторические 27 пропусков — теперь с планом выполнения","",
 "[Отдельная матрица 27 обязательств с этапом, владельцем, подготовкой, критерием сдачи и клиентскими блокерами](MISSING_27_REMEDIATION.md). Даже если учтено — это НЕ означает выполнение.",""]
 for item in q:
  if item["Учли в плане"]=="Нет":
   text.append(f"- **{item['ID']}** ({item['Приоритет']}): {esc(item['Требование'])}. Вопрос: {esc(item['Вопрос заказчику'])}")
 text+=["","## 25 замечаний по договору и вопросов для письменного уточнения","",
 "Это возможные неясности/риски проекта, а не установленная недействительность договора. К: физическая строка договора; ТЗ: физическая строка исходного описания.","",
 "| ID / важность | Вывод | Строки | Вопрос заказчику |","|---|---|---|---|"]
 for item in risks:
  text.append(f"| **{item['ID']} / {item['Риск']}** | {esc(item['Вывод первичной сверки'])} | {item['Строки источника']} | {esc(item['Лаконичный вопрос заказчику'])} |")
 text+=["","## Особое внимание до заключения и до расходов","",
 "1. **Идентификаторы/реквизиты.** Два разных ИКЗ в документах, два разных ОКТМО внутри контракта, некорректные перекрёстные ссылки п. 4.1 и раздела 5. Уточнить письменно; не исправлять чужой контракт односторонне.",
 "2. **Календарь.** Завершение услуг до 07.12.2026; подача документов через ЕИС в пределах 3 рабочих дней после срока; до 20 рабочих дней у заказчика на приёмку и окончание договора 31.12.2026. Сроки могут конфликтовать при позднем завершении. Обязательное личное интервью на территории музея, три концепции по минимум 5 PDF-страниц, презентация в течение двух рабочих дней после получения PDF, решение о выборе.",
 "3. **Цена и обеспечение.** В шаблоне цена, НДС, данные исполнителя и обеспечение НЕ заполнены. Аванса нет; оплата после полного завершения/подписания документов, затем до 7 рабочих дней. Приложение с расчётом имеет две услуги — сайт и фирменный стиль — но это не подтверждает два отдельных платежных этапа.",
 "4. **Исключительные права.** Контракт требует передачи исключительных прав на создаваемые и используемые результаты. GPL TinyMCE, сторонние CMS/библиотеки, чужие изображения, шрифты и коллекции не становятся собственностью исполнителя. Юридически согласовать разграничение авторского кода, лицензированного ПО, исходных медиа и передачи прав по акту; иначе риск отказа в оплате и ответственности по п.2.4.14, 6.3–6.5.",
 "5. **Ответственность и гарантия.** Штрафы считаются по отдельным нарушениям, существенная просрочка свыше 5 рабочих дней может повлечь односторонний отказ. Гарантия 12 месяцев с приёмки, реакция на обращение за 24 часа, устранение сложных дефектов до 5 рабочих дней. Нужен официальный канал обращений и разделение ответственности за сервер музея.",
 "6. **Передача.** Обязательны исходные файлы дизайна, опубликованный сайт, весь согласованный исходный код, ключи в безопасном канале, бумага и носитель, руководство редактора/администратора/пользователя, самостоятельные отчёты тестирования И нагрузочного тестирования, ЕИС-документ, акт услуг, акт исключительных прав. Форма акта предусматривает два подлинника — способ совместить с УКЭП уточнить.",
 "",
 "## Что нельзя считать готовым на основании только дорожной карты","",
 "- Подписанный договор, фактическую дату его заключения и окончательную цену: это исходный проект с пропусками.",
 "- Окончательную айдентику, право на фото/видео, переход исключительных прав на сторонние библиотеки, договорную и юридическую приёмку.",
 "- Производственные серверы музея, API билетов, реальные измерения надёжности под нагрузкой, 12-месячную поддержку и документы заказчика.",
 "- Автоматическую правомерность изменений ТЗ или проекта по 44-ФЗ; этот вопрос должен решать уполномоченный сотрудник/юрист музея.",
 "",
 "## Предлагаемый порядок уточнений","",
 "1. **До подписания**: вопросы D01–D08, D10–D13, D15, D20, D22; назначить ответственного за решения и юридическое согласование сторонних зависимостей.",
 "2. **Первые рабочие дни**: очное интервью, официальный календарь, назначение согласующих (ответ 2 рабочих дня), перечень всех исходников, проверка прав.",
 "3. **Этап концепций**: три самостоятельных комплекта минимум 5 PDF-страниц и презентация в пределах 2 рабочих дней после получения; письменный выбор концепции.",
 "4. **Этап дизайн/сайт**: все форматы фирменных носителей, реальные фото/видео с лицензиями, CMS/ИБ/билеты/структура сайта, демонстрация страниц на устройствах; фиксировать письменные решения.",
 "5. **Перед сдачей**: полный функциональный, доступностный и нагрузочный протокол; сервер и домен заказчика; обучение; акт/ЕИС, перенос доступа и прав; гарантийный регламент 24 ч/5 рабочих дней.",
 "",
 "## Файлы для работы","",
 f"- [{len(q)} индивидуальных вопросов по открытым TZ](OPEN_CUSTOMER_QUESTIONS.md) / [CSV](OPEN_CUSTOMER_QUESTIONS.csv).",
 "- [125 пунктов проекта контракта](CONTRACT_CLAUSE_MAP.md) / [CSV](CONTRACT_CLAUSE_MAP.csv).",
 "- [25 замечаний и вопросов по проекту контракта](CONTRACT_DISCREPANCIES_AND_RISKS.csv).",
 "- [325 требований и их готовность](TZ_EXECUTION_MATRIX.md); [основная дорожная карта](../ROADMAP.md).",
 "- Воспроизводимость: python3 scripts/build_customer_questions_audit.py; python3 scripts/audit_primary_contract.py --source-dir PRIVATE_EIS_FOLDER; python3 scripts/render_primary_audit_summary.py. Первичные Word-файлы и посрочные исходные таблицы не публикуются.",
 ""]
 (OUT/"TZ_CONTRACT_ROADMAP_DEEP_AUDIT.md").write_text("\n".join(text).rstrip("\n")+"\n",encoding="utf-8")
 print('SUMMARY_READY:',len(q),'questions, 125 contract clauses, 25 discrepancy flags, 19 groups; report lines',len(text))
if __name__=="__main__":main()
